else:
pygame.draw.rect(screen, (135, 206, 235), (x, y, block_size, block_size))

# Create a function to draw the current shape
def draw_shape(shape, x, y):
for i in range(len(shape)):
for j in range(len(shape[i])):
if shape[i][j] == 1:
pygame.draw.rect(screen, (255, 0, 0), (x + j * block_size, y + i * block_size, block_size, block_size))

# Create a function to check if the shape has collided with the ground
def check_collision(shape, x, y):
for i in range(len(shape)):
for j in range(len(shape[i])):
if shape[i][j] == 1:
if y + i * block_size < 0 or \
y + i * block_size >= screen_height or \
x + j * block_size < 0 or \
x + j * block_size >= screen_width:
return True
if (x + j * block_size) // block_size + (y + i * block_size) // block_size >= len(board) or \
board[(x + j * block_size) // block_size + (y + i * block_size) // block_size][(y + i * block_size) % block_size][(x + j * block_size) % block_size] == 1:
return True
return False

# Create a function to move the shape left
def move_left(shape, x, y):
return shape, x - block_size, y

# Create a function to move the shape right
def move_right(shape, x, y):
return shape, x + block_size, y

# Create a function to move the shape down
def move_down(shape, x, y):
return shape, x, y - block_size

# Create a function to rotate the shape
def rotate(shape):
new_shape = [[0 for j in range(len(shape[0]))] for i in range(len(shape))]
for i in range(len(shape)):
for j in range(len(shape[i])):
new_shape[len(shape) - 1 - j][i] = shape[i][j]
return new_shape

# Create a function to drop the shape to the ground
