for i in range(len(shape)):
for j in range(len(shape[i])):
if shape[i][j] == 1:
board[x // block_size + j][y // block_size + i] = 1

# Create a function to clear full rows
def clear_rows():
new_board = [[0 for j in range(screen_width // block_size)] for i in range(screen_height // block_size)]
num_rows_cleared = 0
for i in range(len(board)):
if all(row):
for row in board([i]):
num_rows_cleared += 1
else:
for j in range(len(board[i])):
new_board[i - num_rows_cleared][j] = board[i][j]
return new_board, num_rows_cleared

# Create a global variable to store the current shape
current_shape = random.choice(shapes)

# Create a global variable to store the position of the current shape
current_x = screen_width // 2 - len(current_shape[0]) * block_size // 2
current_y = 0

# Create a global variable to store the game board
board = [[[0 for j in range(screen_width // block_size)] for i in range(screen_height // block_size)]]

# Game loop
running = True
while running:
# Handle events
for event in pygame.event.get():
if event.type == pygame.QUIT:
running = False
if event.type == pygame.KEYDOWN:
if event.key == pygame.K_LEFT:
current_shape, current_x, current_y = move_left(current_shape, current_x, current_y)
if event.key == pygame.K_RIGHT:
current_shape, current_x, current_y = move_right(current_shape, current_x, current_y)
if event.key == pygame.K_DOWN:
current_shape, current_x, current_y = move_down(current_shape, current_x, current_y)
if event.key == pygame.K_UP:
current_shape = rotate(current_shape)

# Update the game state
draw_board()
draw_shape(current_shape, current_x, current_y)
pygame.display.update()
time.sleep(block_drop_speed)
current_shape, current_x, current_y = drop_shape(current_shape, current_x, current_y)
if check_collision(current_shape, current_x, current_y):
board, num_rows_cleared = clear_rows()
score += num_rows_cleared * 10
score_text = font.render("Score: {}".format(score), True, (255, 255, 255))
screen.blit(score_text, (10, 10))
current_shape = random.choice(shapes)
current_x = screen_width // 2 - len(current_shape[0]) * block_size // 2
current_y = screen_height - len(board) * block_size

# Quit Pygame
pygame.quit()
sys.exit()
