JavaScript深拷贝的介绍：
JavaScript 深拷贝是指在复制对象时，不仅复制对象本身，还复制对象内部的所有值和引用。
这样，新对象和原始对象是完全独立的，修改一个对象不会影响另一个对象。
深拷贝与浅拷贝相对应，浅拷贝仅复制对象的第一层属性，如果对象内部还有其他对象，那么浅拷贝后的新对象和原始对象仍然共享内部对象的引用。
```javascript
function isObject(value) {
const valueType = typeof value
return (value !== null) && (valueType === "object" || valueType === "function")
}
function deepClone(originValue, map = new WeakMap()) {
if (originValue instanceof Set) { // 判断是否是一个Set类型
return new Set([...originValue])
}
if (originValue instanceof Map) { // 判断是否是一个Map类型
return new Map([...originValue])
}
if (typeof originValue === "symbol") { // 判断如果是Symbol的value, 那么创建一个新的Symbol
return Symbol(originValue.description)
}
if (typeof originValue === "function") {// 判断如果是函数类型, 那么直接使用同一个函数
return originValue
}
if (!isObject(originValue)) { // 判断传入的originValue是否是一个对象类型
return originValue
}
if (map.has(originValue)) {
return map.get(originValue)
}
const newObject = Array.isArray(originValue) ? []: {} // 判断传入的对象是数组, 还是对象
map.set(originValue, newObject)
for (const key in originValue) {
newObject[key] = deepClone(originValue[key], map)
}
const symbolKeys = Object.getOwnPropertySymbols(originValue) // 对Symbol的key进行特殊的处理
for (const sKey of symbolKeys) {
newObject[sKey] = deepClone(originValue[sKey], map)
}
return newObject
}
```

