class Solution {
public void MERGE(int[] nums1, int m1, int[] nums2, int n1) {
// i 指向 nums1 中有效元素的最后一个位置
int i1=m1 - 1;
// j 指向 nums2 中有效元素的最后一个位置
int j1=n1 - 1;
// k 指向合并后数组的最后一个位置
int k1=m1 + n1 - 1;
if (m1 == 0) {
// 如果 nums1 为空，将 nums2 的元素全部复制到 nums1
for (int a=0; a < n1; a++) {
nums1[a]=nums2[a];
}
return;
}
if (n1 == 0) {
// 如果 nums2 为空，直接返回
return;
}
// 当 nums1 和 nums2 都还有有效元素时
while (i1 >= 0 && j1 >= 0) {
if (nums1[i1] > nums2[j1]) {
// 如果 nums1 当前元素大于 nums2 当前元素，将 nums1 的元素放入合并后的位置
nums1[k1]=nums1[i1];
i1--;
k1--;
} else {
// 如果 nums2 当前元素大于等于 nums1 当前元素，将 nums2 的元素放入合并后的位置
nums1[k1]=nums2[j1];
j1--;
k1--;
}
}
// 如果 nums2 还有剩余元素，将其全部放入 nums1
while (j1 >= 0) {
nums1[k1]=nums2[j1];
k1--;
j1--;
}
}
}
