二分查找（Binary Search）是一种在有序数组中查找特定元素的搜索算法。它的工作原理是通过将查找范围逐步缩小一半来快速定位目标值。二分查找的时间复杂度为 O(log n)，这使得它在处理大规模数据时非常高效。

以下是示例代码，展示了如何在 C++ 中实现二分查找算法：

```cpp
#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& arr, int target) {
int left = 0; // 左边界
int right = arr.size() - 1; // 右边界

while (left <= right) { // 当左边界小于等于右边界时，继续查找
int mid = left + (right - left) / 2; // 计算中间位置，避免溢出

if (arr[mid] == target) { // 如果中间值等于目标值
return mid; // 返回中间值的索引
} else if (arr[mid] < target) { // 如果中间值小于目标值
left = mid + 1; // 在右半部分继续查找
} else { // 如果中间值大于目标值
right = mid - 1; // 在左半部分继续查找
}
}

return -1; // 如果没有找到目标值，返回-1
}

int main() {
std::vector<int> arr = {1, 3, 5, 7, 9, 11, 13, 15};
int target = 7;

int result = binarySearch(arr, target);

