```cpp
#include <iostream>
#include <vector>
#include <functional>

using namespace std;

// 定义名为 MountainArray 的类
class MountainArray {
public:
// 构造函数，接收一个 vector<int> 类型的引用并初始化成员变量 data
MountainArray(vector<int>& arr) : data(arr) {}

// 获取指定索引处的元素值
int get(int index) {
return data[index];
}

// 获取当前数组的长度
int length() {
return data.size();
}

private:
// 存储实际数据的私有成员变量
vector<int> data;
};
class Solution {
public:
int findInMountainArray(int target, MountainArray& mountainArr) {
// 找到山脉数组的峰值索引
int peak = lower_bound(0, mountainArr.length() - 1, [&mountainArr](int t) {
return mountainArr.get(t + 1);
},
[&mountainArr](int t) {
return mountainArr.get(t);
});

// 在峰值左侧的升序部分查找目标值
int index = lower_bound(0, peak, [target](int x) {
return target;
},
[&mountainArr](int x) {
return mountainArr.get(x);
});
// 如果找到目标值，返回索引
if (index != peak && mountainArr.get(index) == target) return index;

// 在峰值右侧的降序部分查找目标值
index = lower_bound(peak, mountainArr.length(), [target](int x) {
return -target;
}, [&mountainArr](int x) {
return -mountainArr.get(x);
});
// 如果找到目标值，返回索引
if (index != mountainArr.length() && mountainArr.get(index) == target) return index;

// 如果没有找到目标值，返回 -1
return -1;
}

// 二分查找函数，用于找到第一个不满足条件的索引
int lower_bound(int l, int r, function<int(int)> getTarget, function<int(int)> getCur) {
while (l < r) {
int mid = l + (r - l) / 2;
// 如果当前值小于目标值，说明目标值在右侧
if (getCur(mid) < getTarget(mid)) {
l = mid + 1;
}
else {
// 否则目标值在左侧
r = mid;
}
}
return r;
}
};

int main() {
// 示例数据
vector<int> arr = {1, 2, 3, 4, 5, 3, 1};
MountainArray mountainArr(arr);
Solution sol;

// 测试目标值
int target = 3;

// 调用 findInMountainArray 函数
int result = sol.findInMountainArray(target, mountainArr);

// 输出结果
cout << "Target " << target << " found at index: " << result << endl;

return 0;
}
