let result = 1; // at least one case, with no errors

if (new Set(word).size === n) { // calculate the no-error case
result += n; // if each character is not repeated, then there are n possible error cases
}

for (let i = 0; i < n; i++) { // calculate cases with at most one error
let j = i;
while (j < n && word[j] === word[i]) {
j++;
}
if (j - i > 1) { // find the repeated character
result += (j - i); // each repeated character can be an error position
}
i = j - 1; // skip the repeated character
}

return result;
}

const word = "aabb"; // example usage
console.log(countPossibleStrings(word)); // expected output: 5
```

