JavaScript Deep Clone Introduction:
JavaScript deep cloning refers to copying an object completely, including all values and references within the object.
This way, the new object and the original object are completely independent, and modifying one object will not affect the other.
Deep cloning is contrasted with shallow cloning, which only copies the first level of properties of an object. If the object contains other objects internally, the new object and the original object will still share references to these internal objects after shallow cloning.
```javascript
function isObject(value) {
const valueType = typeof value
return (value !== null) && (valueType === "object" || valueType === "function")
}
function deepClone(originValue, map = new WeakMap()) {
if (originValue instanceof Set) { // check if it's a Set type
return new Set([...originValue])
}
if (originValue instanceof Map) { // check if it's a Map type
return new Map([...originValue])
}
if (typeof originValue === "symbol") { // check if it's a Symbol value, create a new Symbol
return Symbol(originValue.description)
}
if (typeof originValue === "function") { // check if it's a function type, use the same function
return originValue
}
if (!isObject(originValue)) { // check if the originValue is an object type
return originValue
}
if (map.has(originValue)) {
return map.get(originValue)
}
const newObject = Array.isArray(originValue) ? [] : {} // check if the object is an array or object
map.set(originValue, newObject)
for (const key in originValue) {
newObject[key] = deepClone(originValue[key], map)
}
const symbolKeys = Object.getOwnPropertySymbols(originValue) // special handling for Symbol keys
for (const sKey of symbolKeys) {
newObject[sKey] = deepClone(originValue[sKey], map)
}
return newObject
}
```

